// 서울 열린데이터광장 "서울시 공공체육시설 정보"(OA-21779, service=facilities)에서
// FT_KIND_NAME이 "수영장"인 항목만 걸러서 받아온 서울시내 공공 수영장 110곳.
// 전국공공시설개방정보표준데이터(publicPoolFacilities.ts)엔 서울 소재 시설이 하나도
// 없어서(회현체육관 등) 빠져 있던 부분을 이걸로 보완한다 — poolData.ts에서 같이 병합 검색.
//
// 이 API 자체엔 위도/경도가 없어서, 주소(roadAddress)를 OpenStreetMap Nominatim으로
// 지오코딩해서 좌표를 채웠다(키 불필요, 무료) — 110곳 중 109곳은 정확한 건물/부지 좌표를
// 찾았고(도로명 "N길" 가지번호는 띄어쓰기 없이 붙여써야 매칭됨, 예: "퇴계로12길"), 망원
// 한강공원 수영장은 시설명으로 공원 전체 위치를 잡았다. 물빛수영장 1곳만 끝내 못 찾아서
// lat/lng을 null로 남겨뒀다 — 좌표를 지어내지 않고, 지도 핀 대신 주소 검색 링크로 대체된다
// (poolData.ts의 mapLinkFor 폴백).
//
// sizeText(FT_SIZE)엔 실제 레일 수가 자유 텍스트로 들어있는 경우가 많아 그대로 보존했고
// (예: "성인풀 5레인 / 면적 5,714.8m²"), freeSwimInfo(FT_INFO_TIME)엔 자유수영 운영 안내가
// 있을 때만 채워진다. 역시 수업시간대별 구분·잔여석은 원 데이터에 없어서 넣지 않았다.
//
// 생성: data.seoul.go.kr "서울시 공공체육시설 정보" API 전체 897건 중 수영장 110건 추출,
// Nominatim 지오코딩 (2026-10-04 기준).

export interface SeoulPoolFacility {
  id: string;
  name: string;
  district: string | null;
  roadAddress: string;
  lat: number | null;
  lng: number | null;
  phone: string | null;
  statusName: string;
  sizeText: string | null;
  operWeekday: string | null;
  operWeekend: string | null;
  freeSwimInfo: string | null;
  feeText: string | null;
  amenities: string | null;
  homepageUrl: string | null;
  institution: string | null;
  notes: string | null;
  rentable: string | null;
}

